@Test
public void testSingleFieldGroupInList() throws Exception {
    // this tests the case where non-avro older data has an ambiguous list
    Path test = writeDirect("message SingleFieldGroupInList {" + "  optional group single_element_groups (LIST) {" + "    repeated group single_element_group {" + "      required int64 count;" + "    }" + "  }" + "}", new DirectWriter() {

        @Override
        public void write(RecordConsumer rc) {
            rc.startMessage();
            rc.startField("single_element_groups", 0);
            rc.startGroup();
            // start writing array contents
            rc.startField("single_element_group", 0);
            rc.startGroup();
            rc.startField("count", 0);
            rc.addLong(1234L);
            rc.endField("count", 0);
            rc.endGroup();
            rc.startGroup();
            rc.startField("count", 0);
            rc.addLong(2345L);
            rc.endField("count", 0);
            rc.endGroup();
            // finished writing array contents
            rc.endField("single_element_group", 0);
            rc.endGroup();
            rc.endField("single_element_groups", 0);
            rc.endMessage();
        }
    });
    // can't tell from storage whether this should be a list of single-field
    // records or if the single_field_group layer is synthetic.
    // old behavior - assume that the repeated type is the element type
    Schema singleElementGroupSchema = record("single_element_group", field("count", primitive(Schema.Type.LONG)));
    Schema oldSchema = record("SingleFieldGroupInList", optionalField("single_element_groups", array(singleElementGroupSchema)));
    GenericRecord oldRecord = instance(oldSchema, "single_element_groups", Arrays.asList(instance(singleElementGroupSchema, "count", 1234L), instance(singleElementGroupSchema, "count", 2345L)));
    assertReaderContains(oldBehaviorReader(test), oldSchema, oldRecord);
    // new behavior - assume that single_element_group is synthetic (in spec)
    Schema newSchema = record("SingleFieldGroupInList", optionalField("single_element_groups", array(primitive(Schema.Type.LONG))));
    GenericRecord newRecord = instance(newSchema, "single_element_groups", Arrays.asList(1234L, 2345L));
    assertReaderContains(newBehaviorReader(test), newSchema, newRecord);
}

@Test
public void testSingleFieldGroupInListWithSchema() throws Exception {
    // this tests the case where older data has an ambiguous structure, but the
    // correct interpretation can be determined from the avro schema
    Schema singleElementRecord = record("single_element_group", field("count", primitive(Schema.Type.LONG)));
    Schema expectedSchema = record("SingleFieldGroupInList", optionalField("single_element_groups", array(singleElementRecord)));
    Map<String, String> metadata = new HashMap<String, String>();
    metadata.put(AvroWriteSupport.AVRO_SCHEMA, expectedSchema.toString());
    Path test = writeDirect("message SingleFieldGroupInList {" + "  optional group single_element_groups (LIST) {" + "    repeated group single_element_group {" + "      required int64 count;" + "    }" + "  }" + "}", new DirectWriter() {

        @Override
        public void write(RecordConsumer rc) {
            rc.startMessage();
            rc.startField("single_element_groups", 0);
            rc.startGroup();
            // start writing array contents
            rc.startField("single_element_group", 0);
            rc.startGroup();
            rc.startField("count", 0);
            rc.addLong(1234L);
            rc.endField("count", 0);
            rc.endGroup();
            rc.startGroup();
            rc.startField("count", 0);
            rc.addLong(2345L);
            rc.endField("count", 0);
            rc.endGroup();
            // finished writing array contents
            rc.endField("single_element_group", 0);
            rc.endGroup();
            rc.endField("single_element_groups", 0);
            rc.endMessage();
        }
    }, metadata);
    GenericRecord expectedRecord = instance(expectedSchema, "single_element_groups", Arrays.asList(instance(singleElementRecord, "count", 1234L), instance(singleElementRecord, "count", 2345L)));
    // both should behave the same way because the schema is present
    assertReaderContains(oldBehaviorReader(test), expectedSchema, expectedRecord);
    assertReaderContains(newBehaviorReader(test), expectedSchema, expectedRecord);
}

@Test
public void testNewOptionalGroupInList() throws Exception {
    Path test = writeDirect("message NewOptionalGroupInList {" + "  optional group locations (LIST) {" + "    repeated group list {" + "      optional group element {" + "        required double latitude;" + "        required double longitude;" + "      }" + "    }" + "  }" + "}", new DirectWriter() {

        @Override
        public void write(RecordConsumer rc) {
            rc.startMessage();
            rc.startField("locations", 0);
            rc.startGroup();
            // start writing array contents
            rc.startField("list", 0);
            // write a non-null element
            // array level
            rc.startGroup();
            rc.startField("element", 0);
            rc.startGroup();
            rc.startField("latitude", 0);
            rc.addDouble(0.0);
            rc.endField("latitude", 0);
            rc.startField("longitude", 1);
            rc.addDouble(0.0);
            rc.endField("longitude", 1);
            rc.endGroup();
            rc.endField("element", 0);
            // array level
            rc.endGroup();
            // write a null element (element field is omitted)
            // array level
            rc.startGroup();
            // array level
            rc.endGroup();
            // write a second non-null element
            // array level
            rc.startGroup();
            rc.startField("element", 0);
            rc.startGroup();
            rc.startField("latitude", 0);
            rc.addDouble(0.0);
            rc.endField("latitude", 0);
            rc.startField("longitude", 1);
            rc.addDouble(180.0);
            rc.endField("longitude", 1);
            rc.endGroup();
            rc.endField("element", 0);
            // array level
            rc.endGroup();
            // finished writing array contents
            rc.endField("list", 0);
            rc.endGroup();
            rc.endField("locations", 0);
            rc.endMessage();
        }
    });
    Schema location = record("element", field("latitude", primitive(Schema.Type.DOUBLE)), field("longitude", primitive(Schema.Type.DOUBLE)));
    // old behavior - assume that the repeated type is the element type
    Schema elementRecord = record("list", optionalField("element", location));
    Schema oldSchema = record("NewOptionalGroupInList", optionalField("locations", array(elementRecord)));
    GenericRecord oldRecord = instance(oldSchema, "locations", Arrays.asList(instance(elementRecord, "element", instance(location, "latitude", 0.0, "longitude", 0.0)), instance(elementRecord), instance(elementRecord, "element", instance(location, "latitude", 0.0, "longitude", 180.0))));
    assertReaderContains(oldBehaviorReader(test), oldSchema, oldRecord);
    // new behavior - assume that single_element_group is synthetic (in spec)
    Schema newSchema = record("NewOptionalGroupInList", optionalField("locations", array(optional(location))));
    GenericRecord newRecord = instance(newSchema, "locations", Arrays.asList(instance(location, "latitude", 0.0, "longitude", 0.0), null, instance(location, "latitude", 0.0, "longitude", 180.0)));
    assertReaderContains(newBehaviorReader(test), newSchema, newRecord);
}

