@Test
public void testAvroCompatListInList() throws Exception {
    Path test = writeDirect("message AvroCompatListInList {" + "  optional group listOfLists (LIST) {" + "    repeated group array (LIST) {" + "      repeated int32 array;" + "    }" + "  }" + "}", new DirectWriter() {

        @Override
        public void write(RecordConsumer rc) {
            rc.startMessage();
            rc.startField("locations", 0);
            rc.startGroup();
            // start writing array contents
            rc.startField("array", 0);
            rc.startGroup();
            // start writing inner array contents
            rc.startField("array", 0);
            // write [34, 35, 36]
            rc.addInteger(34);
            rc.addInteger(35);
            rc.addInteger(36);
            // finished writing inner array contents
            rc.endField("array", 0);
            rc.endGroup();
            // write an empty list
            rc.startGroup();
            rc.endGroup();
            rc.startGroup();
            // start writing inner array contents
            rc.startField("array", 0);
            // write [32, 33, 34]
            rc.addInteger(32);
            rc.addInteger(33);
            rc.addInteger(34);
            // finished writing inner array contents
            rc.endField("array", 0);
            rc.endGroup();
            // finished writing array contents
            rc.endField("array", 0);
            rc.endGroup();
            rc.endField("locations", 0);
            rc.endMessage();
        }
    });
    Schema listOfLists = array(array(primitive(Schema.Type.INT)));
    Schema oldSchema = record("AvroCompatListInList", optionalField("listOfLists", listOfLists));
    GenericRecord oldRecord = instance(oldSchema, "listOfLists", Arrays.asList(Arrays.asList(34, 35, 36), Arrays.asList(), Arrays.asList(32, 33, 34)));
    // both should detect the "array" name
    assertReaderContains(oldBehaviorReader(test), oldSchema, oldRecord);
    assertReaderContains(newBehaviorReader(test), oldSchema, oldRecord);
}

