        for (int i = 1; i < 32; i++) {
            LOG.debug("Width: " + i);
            int[] packed = new int[i];
            int[] unpacked = new int[32];
            int[] values = generateValues(i);
            // pack lemire
            final IntPacker packer = pack.newIntPacker(i);
            packer.pack32Values(values, 0, packed, 0);
