@Test
public void testScroogeBinaryEncoding() throws Exception {
    StringAndBinary expected = new StringAndBinary.Immutable("test", ByteBuffer.wrap(new byte[] { -123, 20, 33 }));
    File temp = tempDir.newFile(UUID.randomUUID().toString());
    temp.deleteOnExit();
    temp.delete();
    Path path = new Path(temp.getPath());
    ParquetWriter<StringAndBinary> writer = new ParquetWriter<StringAndBinary>(path, new Configuration(), new ScroogeWriteSupport<StringAndBinary>(StringAndBinary.class));
    writer.write(expected);
    writer.close();
    // read using the parquet-thrift version to isolate the write path
    ParquetReader<org.apache.parquet.thrift.test.binary.StringAndBinary> reader = ThriftParquetReader.<org.apache.parquet.thrift.test.binary.StringAndBinary>build(path).withThriftClass(org.apache.parquet.thrift.test.binary.StringAndBinary.class).build();
    org.apache.parquet.thrift.test.binary.StringAndBinary record = reader.read();
    reader.close();
    Assert.assertEquals("String should match after serialization round trip", "test", record.s);
    Assert.assertEquals("ByteBuffer should match after serialization round trip", ByteBuffer.wrap(new byte[] { -123, 20, 33 }), record.b);
}

