@Test
public void testBinary() throws IOException {
    StringAndBinary expected = new StringAndBinary("test", ByteBuffer.wrap(new byte[] { -123, 20, 33 }));
    File temp = tempDir.newFile(UUID.randomUUID().toString());
    temp.deleteOnExit();
    temp.delete();
    Path path = new Path(temp.getPath());
    ThriftParquetWriter<StringAndBinary> writer = new ThriftParquetWriter<StringAndBinary>(path, StringAndBinary.class, CompressionCodecName.SNAPPY);
    writer.write(expected);
    writer.close();
    ParquetReader<StringAndBinary> reader = ThriftParquetReader.<StringAndBinary>build(path).withThriftClass(StringAndBinary.class).build();
    StringAndBinary record = reader.read();
    reader.close();
    Assert.assertEquals("Should match after serialization round trip", expected, record);
}

